<!doctype html>
<html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Acceso empresarial | TechMarket</title><link rel="stylesheet" href="css/styles.css"><style>
body{min-height:100vh;background:linear-gradient(135deg,#0f2027,#203a43,#2c5364);display:grid;place-items:center;padding:20px}.private-card{width:min(100%,490px);background:#fff;border-radius:22px;padding:32px;box-shadow:0 22px 65px #0004}.private-card h1{margin:0 0 8px}.private-card p{color:#64748b}.private-card label{display:block;margin:14px 0 6px;font-weight:600}.private-card input,.private-card select{width:100%;padding:13px;border:1px solid #cbd5e1;border-radius:10px;margin-top:6px}.private-card button{width:100%;margin-top:18px}.private-card .alert{color:#b91c1c;margin-top:12px}.private-card .muted{font-size:13px;color:#64748b}.brand{font-size:13px;letter-spacing:2px;color:#4f46e5;font-weight:800}.hide{display:none!important}
</style></head><body><main class="private-card">
  <div class="brand" id="companyBrand">
    <img id="companyLogo" src="" alt="Logo de la empresa" class="hide">
    <span id="companyName">TECHMARKET ONLINE</span>
    <span>· ÁREA PRIVADA</span>
</div>
  <h1 id="title">Acceso empresarial</h1><p id="subtitle">Ingresa con el correo y contraseña que te entregó el Jefe.</p><div id="formArea"><p>Comprobando configuración…</p></div><div id="error" class="alert" role="alert"></div><p class="muted">Esta pantalla es exclusiva para Jefe, Administradores y Empleados. Las cuentas de clientes no tienen acceso al panel.</p><a href="index.html" style="color:#4f46e5">← Volver a la tienda pública</a></main>
<script>
const area=document.getElementById('formArea'),errorBox=document.getElementById('error');const params=new URLSearchParams(location.search);let needsSetup=false;
(async function loadCompanyIdentity(){try{const r=await fetch('api_marca.php',{cache:'no-store'});if(!r.ok)return;const d=await r.json();const name=String(d.company_name||'TechMarket Online').trim()||'TechMarket Online';const label=document.getElementById('companyName');if(label)label.textContent=name;document.title='Acceso empresarial | '+name;const logo=document.getElementById('companyLogo');if(logo&&d.logo_url){logo.src=d.logo_url;logo.classList.remove('hide');}}catch(_){}})();
function safeReturn(){const r=params.get('return')||'#/admin/dashboard';return r.startsWith('#/admin/')||r==='#/admin'?'index.html'+r:'index.html#/admin/dashboard'}
function showLogin(){document.getElementById('title').textContent='Acceso empresarial';document.getElementById('subtitle').textContent='Ingresa con las credenciales que te entregó el Jefe.';area.innerHTML=`<form id="loginForm"><label>Correo empresarial<input type="email" id="correo" autocomplete="username" required placeholder="nombre@empresa.com"></label><label>Contraseña<input type="password" id="pass" autocomplete="current-password" required></label><button class="btn" type="submit">Iniciar sesión</button></form>`;document.getElementById('loginForm').addEventListener('submit',async e=>{e.preventDefault();await send({action:'login',correo:document.getElementById('correo').value,contrasena:document.getElementById('pass').value},true)})}
function showSetup(){document.getElementById('title').textContent='Configurar cuenta Jefe';document.getElementById('subtitle').textContent='No hay una cuenta Jefe todavía. Crea la cuenta principal desde este equipo con XAMPP.';area.innerHTML=`<form id="setupForm"><label>Correo del Jefe<input type="email" id="correo" autocomplete="username" required placeholder="jefe@techmarket.co"></label><label>Contraseña principal<input type="password" id="pass" autocomplete="new-password" minlength="12" required></label><label>Confirmar contraseña<input type="password" id="pass2" autocomplete="new-password" minlength="12" required></label><button class="btn" type="submit">Crear cuenta Jefe</button></form><p class="muted">Usa una contraseña única de al menos 12 caracteres. El Jefe será la única cuenta que podrá crear Administradores y Empleados.</p>`;document.getElementById('setupForm').addEventListener('submit',async e=>{e.preventDefault();const pass=document.getElementById('pass').value;if(pass!==document.getElementById('pass2').value){errorBox.textContent='Las contraseñas no coinciden.';return}await send({action:'setup_owner',correo:document.getElementById('correo').value,contrasena:pass},true)})}
async function send(payload,redirect){errorBox.textContent='';try{const r=await fetch('api_auth.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const d=await r.json();if(!r.ok)throw new Error(d.error||'No se pudo completar la solicitud.');if(redirect)location.href=safeReturn();}catch(e){errorBox.textContent=e.message||'Error de conexión.'}}
(async()=>{try{const r=await fetch('api_auth.php?action=status',{cache:'no-store'});const d=await r.json();if(d.authenticated){location.href=safeReturn();return}if(d.needs_setup){if(!['127.0.0.1','::1'].includes(location.hostname==='localhost'?'127.0.0.1':location.hostname)){area.innerHTML='<div class="alert">La creación inicial del Jefe solo está habilitada desde localhost en XAMPP. Abre esta página en el equipo servidor.</div>';return}showSetup()}else showLogin()}catch(e){area.innerHTML='<div class="alert">No se pudo conectar con la API. Comprueba que Apache y la conexión de MySQL estén funcionando.</div>'}})();
</script></body></html>
